                # rate column may be named 'rate', 'USD/EUR', etc.; try common names
                for key in ["rate", "USD/EUR", "USD_EUR", "USD/EUR closing rate"]:
                    if key in row and row[key]:
                        try:
                            return float(row[key])
                        except ValueError:
                            continue
                # fallback: any numeric value in row
                for val in row.values():
                    try:
                        return float(val)
                    except ValueError:
                        continue
    raise KeyError(f"Date {date} not found in {csv_path}")

def median(nums: list) -> float:
    """Return the median of a non-empty list of numbers (mean of the two middle values for even length)."""
    if not nums:
        raise ValueError("median requires a non-empty list")
    sorted_nums = sorted(nums)
    n = len(sorted_nums)
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_nums[mid])
    else:
        return (sorted_nums[mid - 1] + sorted_nums[mid]) / 2.0

def c_to_f(c: float) -> float:
    """Convert Celsius to Fahrenheit (F = C * 9/5 + 32), rounded to 1 decimal."""
    return round(c * 9 / 5 + 32, 1)

def dedupe(xs: list) -> list:
    """Remove duplicates, keeping the first occurrence of each element in original order."""
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def sort_versions(vs: list) -> list:
    """Sort semantic version strings ascending by (major, minor, patch)."""
    def key(v: str):
        try:
            parts = v.split('.')
            return tuple(int(p.lstrip('0') or '0') for p in parts)
        except Exception:
            return v
    return sorted(vs, key=key)

def flatten(xs: list) -> list:
    """Flatten an arbitrarily nested list of ints, preserving left-to-right order."""
    result = []
    for item in xs:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def valid_parens(s: str) -> bool:
    """Return True if every (, [, { is closed by the matching bracket in the right order."""
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

def camel_to_snake(s: str) -> str:
    """Convert camelCase or PascalCase to snake_case. Consecutive capitals stay together (HTTPServer -> http_server)."""
    import re
    # Insert underscore before each uppercase letter that is not at the start
    return re.sub(r"(?<!^)(?=[A-Z])", "_", s).lower()
